a2.textContent="(function() {\n  var root = document.getElementById('"+a1+"');\n  var target = document.getElementById('"+a1+"_yt_target');\n  var shield = document.getElementById('"+a1+"_shield');\n  var centerBtn = document.getElementById('"+a1+"_center_btn');\n  var centerIcon = document.getElementById('"+a1+"_center_icon');\n  var controls = document.getElementById('"+a1+"_controls');\n  var playBtn = document.getElementById('"+a1+"_play_btn');\n  var playIcon = document.getElementById('"+a1+"_play_icon');\n  var rewindBtn = document.getElementById('"+a1+"_rewind_btn');\n  var forwardBtn = document.getElementById('"+a1+"_forward_btn');\n  var progressContainer = document.getElementById('"+a1+"_progress_container');\n  var progressFill = document.getElementById('"+a1+"_progress_fill');\n  var scrubber = document.getElementById('"+a1+"_scrubber');\n  var timeTxt = document.getElementById('"+a1+"_time_txt');\n  var speedBtn = document.getElementById('"+a1+"_speed_btn');\n  var speedTxt = document.getElementById('"+a1+"_speed_txt');\n  var speedMenu = document.getElementById('"+a1+"_speed_menu');\n  var fsBtn = document.getElementById('"+a1+"_fs_btn');\n\n  if (!root || !target) return;\n\n  var player = null;\n  var isPlaying = false;\n  var currentTime = 0;\n  var duration = 0;\n  var currentSpeed = 1.0;\n  var hideControlsTimer = null;\n  var isDragging = false;\n  var progressInterval = null;\n\n  function formatTime(sec) {\n    var s = Math.floor(sec || 0);\n    var m = Math.floor(s / 60);\n    var h = Math.floor(m / 60);\n    m = m % 60;\n    s = s % 60;\n    if (h > 0) {\n      return (h < 10 ? '0' + h : h) + ':' + (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s);\n    }\n    return (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s);\n  }\n\n  function updatePlayIcons(playing) {\n    isPlaying = playing;\n    var playPath = '<path d=\"M8 5v14l11-7z\"/>';\n    var pausePath = '<path d=\"M6 19h4V5H6v14zm8-14v14h4V5h-4z\"/>';\n    \n    if (playIcon) playIcon.innerHTML = isPlaying ? pausePath : playPath;\n    if (centerIcon) centerIcon.innerHTML = isPlaying ? pausePath : playPath;\n    \n    if (centerBtn) {\n      centerBtn.style.opacity = isPlaying ? '0' : '1';\n      centerBtn.style.pointerEvents = isPlaying ? 'none' : 'auto';\n    }\n  }\n\n  function togglePlay() {\n    if (!player) return;\n    if (isPlaying) {\n      if (typeof player.pauseVideo === 'function') player.pauseVideo();\n      updatePlayIcons(false);\n      showControls(false);\n    } else {\n      if (typeof player.playVideo === 'function') player.playVideo();\n      updatePlayIcons(true);\n      startHideTimer();\n    }\n  }\n\n  function seekRelative(offset) {\n    if (!player || typeof player.getCurrentTime !== 'function') return;\n    var cur = player.getCurrentTime() || currentTime;\n    var dur = (typeof player.getDuration === 'function' ? player.getDuration() : duration) || 999999;\n    var targetTime = Math.max(0, Math.min(dur, cur + offset));\n    player.seekTo(targetTime, true);\n    currentTime = targetTime;\n    updateProgressUI();\n  }\n\n  function updateProgressUI() {\n    if (!timeTxt || !progressFill) return;\n    timeTxt.innerText = formatTime(currentTime) + ' / ' + formatTime(duration);\n    if (duration > 0) {\n      var pct = Math.min(100, Math.max(0, (currentTime / duration) * 100));\n      progressFill.style.width = pct + '%';\n      if (scrubber) scrubber.style.left = pct + '%';\n    }\n  }\n\n  function showControls(autoHide) {\n    if (controls) controls.style.opacity = '1';\n    if (autoHide && isPlaying) {\n      startHideTimer();\n    }\n  }\n\n  function startHideTimer() {\n    clearTimeout(hideControlsTimer);\n    hideControlsTimer = setTimeout(function() {\n      if (isPlaying && controls && speedMenu.style.display !== 'block') {\n        controls.style.opacity = '0';\n      }\n    }, 3000);\n  }\n\n  // Load and initialize YouTube Iframe API\n  function initYT() {\n    player = new YT.Player('"+a1+"_yt_target', {\n      videoId: '"+s.c+"',\n      height: '100%',\n      width: '100%',\n      playerVars: {\n        autoplay: 0,\n        controls: 0,\n        modestbranding: 1,\n        rel: 0,\n        showinfo: 0,\n        iv_load_policy: 3,\n        disablekb: 1,\n        fs: 0,\n        cc_load_policy: 0,\n        playsinline: 1,\n        enablejsapi: 1,\n        start: "+s.d+",\n        origin: window.location.origin\n      },\n      events: {\n        onReady: function(e) {\n          try {\n            duration = e.target.getDuration() || 0;\n            updateProgressUI();\n            var ifr = e.target.getIframe();\n            if (ifr) {\n              ifr.style.pointerEvents = 'none'; // Lock direct clicks on YouTube iframe\n            }\n          } catch(err) {}\n        },\n        onStateChange: function(e) {\n          if (e.data === YT.PlayerState.PLAYING) {\n            updatePlayIcons(true);\n            try {\n              duration = player.getDuration() || duration;\n            } catch(err) {}\n          } else if (e.data === YT.PlayerState.PAUSED || e.data === YT.PlayerState.ENDED) {\n            updatePlayIcons(false);\n          }\n        }\n      }\n    });\n\n    // Start Real-time Progress Tracking Loop\n    clearInterval(progressInterval);\n    progressInterval = setInterval(function() {\n      if (player && typeof player.getCurrentTime === 'function' && !isDragging) {\n        try {\n          var cur = player.getCurrentTime();\n          var dur = player.getDuration();\n          if (dur && dur > 0) duration = dur;\n          if (cur !== undefined && cur !== null) {\n            currentTime = cur;\n            updateProgressUI();\n          }\n        } catch(err) {}\n      }\n    }, 250);\n  }\n\n  // Ensure YT API script is in document\n  if (!window.YT || !window.YT.Player) {\n    if (!document.getElementById('yt_api_script')) {\n      var tag = document.createElement('script');\n      tag.id = 'yt_api_script';\n      tag.src = \"https://www.youtube.com/iframe_api\";\n      var firstScriptTag = document.getElementsByTagName('script')[0];\n      firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);\n    }\n    var checkCount = 0;\n    var ytChecker = setInterval(function() {\n      checkCount++;\n      if (window.YT && window.YT.Player) {\n        clearInterval(ytChecker);\n        initYT();\n      }\n      if (checkCount > 100) clearInterval(ytChecker);\n    }, 100);\n  } else {\n    initYT();\n  }\n\n  // Shield Click -> Toggle Play\n  if (shield) {\n    shield.addEventListener('click', function(e) {\n      e.stopPropagation();\n      speedMenu.style.display = 'none';\n      togglePlay();\n    });\n  }\n\n  if (centerBtn) {\n    centerBtn.addEventListener('click', function(e) {\n      e.stopPropagation();\n      togglePlay();\n    });\n  }\n\n  if (playBtn) {\n    playBtn.addEventListener('click', function(e) {\n      e.stopPropagation();\n      togglePlay();\n    });\n  }\n\n  if (rewindBtn) {\n    rewindBtn.addEventListener('click', function(e) {\n      e.stopPropagation();\n      seekRelative(-10);\n    });\n  }\n\n  if (forwardBtn) {\n    forwardBtn.addEventListener('click', function(e) {\n      e.stopPropagation();\n      seekRelative(10);\n    });\n  }\n\n  // Progress Bar Drag & Click Seeking\n  function handleSeek(e) {\n    if (!player) return;\n    var rect = progressContainer.getBoundingClientRect();\n    var clientX = e.touches ? e.touches[0].clientX : e.clientX;\n    var pos = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));\n    var dur = (typeof player.getDuration === 'function' ? player.getDuration() : duration) || duration;\n    if (dur > 0) {\n      var target = pos * dur;\n      currentTime = target;\n      if (typeof player.seekTo === 'function') {\n        player.seekTo(target, true);\n      }\n      updateProgressUI();\n    }\n  }\n\n  if (progressContainer) {\n    progressContainer.addEventListener('mousedown', function(e) {\n      isDragging = true;\n      handleSeek(e);\n    });\n    progressContainer.addEventListener('touchstart', function(e) {\n      isDragging = true;\n      handleSeek(e);\n    }, {passive: true});\n  }\n\n  window.addEventListener('mousemove', function(e) {\n    if (isDragging) handleSeek(e);\n  });\n  window.addEventListener('mouseup', function() {\n    isDragging = false;\n  });\n  window.addEventListener('touchmove', function(e) {\n    if (isDragging) handleSeek(e);\n  }, {passive: true});\n  window.addEventListener('touchend', function() {\n    isDragging = false;\n  });\n\n  // Speed Selector\n  if (speedBtn) {\n    speedBtn.addEventListener('click', function(e) {\n      e.stopPropagation();\n      speedMenu.style.display = (speedMenu.style.display === 'block') ? 'none' : 'block';\n    });\n  }\n\n  var speedOpts = root.querySelectorAll('.speed-opt');\n  speedOpts.forEach(function(opt) {\n    opt.addEventListener('click', function(e) {\n      e.stopPropagation();\n      var spd = parseFloat(opt.getAttribute('data-speed'));\n      currentSpeed = spd;\n      if (player && typeof player.setPlaybackRate === 'function') {\n        player.setPlaybackRate(spd);\n      }\n      if (speedTxt) speedTxt.innerText = spd + 'x';\n      speedOpts.forEach(function(o) {\n        o.style.color = '#E2E8F0';\n        o.style.fontWeight = 'normal';\n      });\n      opt.style.color = '#6366F1';\n      opt.style.fontWeight = 'bold';\n      speedMenu.style.display = 'none';\n    });\n  });\n\n  document.addEventListener('click', function() {\n    if (speedMenu) speedMenu.style.display = 'none';\n  });\n\n  // Fullscreen\n  if (fsBtn) {\n    fsBtn.addEventListener('click', function(e) {\n      e.stopPropagation();\n      if (!document.fullscreenElement) {\n        if (root.requestFullscreen) root.requestFullscreen();\n        else if (root.webkitRequestFullscreen) root.webkitRequestFullscreen();\n      } else {\n        if (document.exitFullscreen) document.exitFullscreen();\n      }\n    });\n  }\n\n  // Hover & UI control visibility\n  root.addEventListener('mousemove', function() {\n    showControls(true);\n  });\n  root.addEventListener('touchstart', function() {\n    showControls(true);\n  }, {passive: true});\n  root.addEventListener('mouseleave', function() {\n    if (isPlaying) {\n      clearTimeout(hideControlsTimer);\n      if (controls) controls.style.opacity = '0';\n    }\n  });\n\n  // Prevent Context Menu\n  root.addEventListener('contextmenu', function(e) {\n    e.preventDefault();\n    e.stopPropagation();\n    return false;\n  });\n\n})();\n"
